package jp.mintymc.patpat.paper;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Properties;

/** Per-viewer URL-free map-image styles generated by resourcepack/build.py. */
final class SkinCatalog {
    record Skin(String id,String label,int frames,int durationMs,
                float scaleX,float scaleY,float offsetX,float offsetY,float offsetZ,
                String sound,float volume,float pitchMin,float pitchMax) {
        int at(int elapsedTick,int ticks) {
            return Math.min(frames-1,Math.max(0,(int)((long)elapsedTick*frames/Math.max(1,ticks))));
        }
    }
    private final Map<String,Skin> skins;

    private SkinCatalog(Map<String,Skin> skins) {
        this.skins=Map.copyOf(skins);
    }
    static SkinCatalog load() {
        Properties p=new Properties();
        try(InputStream in=SkinCatalog.class.getResourceAsStream("/patpat-skins.properties")) {
            if(in!=null)p.load(new InputStreamReader(in,StandardCharsets.UTF_8));
        }catch(Exception ex) {
            throw new IllegalStateException("Cannot load PatPat skin catalog",ex);
        }
        Map<String,Skin> all=new LinkedHashMap<>();
        String list=p.getProperty("skins","default");
        for(String token:list.split(",")) {
            String id=token.trim().toLowerCase(Locale.ROOT);
            if(!id.matches("[a-z0-9_-]{1,36}"))continue;
            String key="skin."+id+".";
            int count=(int)decimal(p,key+"frames",5,1,48);
            int length=(int)decimal(p,key+"duration-ms",300,50,10000);
            Skin style=new Skin(id,p.getProperty(key+"label",id),count,length,
                (float)decimal(p,key+"scale-x",1,0.1,8),
                (float)decimal(p,key+"scale-y",1,0.1,8),
                (float)decimal(p,key+"offset-x",0,-4,4),
                (float)decimal(p,key+"offset-y",0,-4,4),
                (float)decimal(p,key+"offset-z",0,-4,4),
                p.getProperty(key+"sound",""),
                (float)decimal(p,key+"sound-volume",0.65,0,4),
                (float)decimal(p,key+"sound-pitch-min",0.9,0.1,4),
                (float)decimal(p,key+"sound-pitch-max",1.1,0.1,4));
            all.put(id,style);
        }
        all.putIfAbsent("default",new Skin("default","Default",5,300,1,1,0,0,0,"",0.65f,0.9f,1.1f));
        return new SkinCatalog(all);
    }
    private static double decimal(Properties p,String key,double fallback,double min,double max) {
        try {
            double n=Double.parseDouble(p.getProperty(key,Double.toString(fallback)));
            return Double.isFinite(n)?Math.max(min,Math.min(max,n)):fallback;
        }catch(NumberFormatException ex){return fallback;}
    }
    Skin get(String id) {return skins.getOrDefault(id,skins.get("default"));}
    boolean contains(String id) {return id!=null && skins.containsKey(id);}
    List<String> ids() {return new ArrayList<>(skins.keySet()).stream().sorted((a,b)->
        a.equals("default")?-1:b.equals("default")?1:a.compareTo(b)).toList();}
    String description() {
        return String.join(", ",ids().stream().map(id->id+" ("+get(id).label()+")").toList());
    }
}
